const BASE = process.env.BILLING_URL;
export async function createInvoice(cmd, { signal } = {}) {
  const res = await fetch(`${BASE}/invoices`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(cmd),
    signal,
  });
  if (!res.ok) throw new BillingError(res.status, await res.text());  // translate
  return res.json();
}
